famOriginal27 = load("C:/Users/leechanghoon/Documents/Codex/2026-09-21/snr-svd/tempestsdr-cloud/research/mobile_mipi_leakage/matlab_agentic_lab/results/iphone6_fc100_fam_20261026/refined/rf78_block1/fam.mat","result");
%%
%[text] ## G(k)는 지연 후보에 따른 상관함수
%[text] 아래 식에서 r은 기준 템플릿, v는 관측 파형이다. 두 파형에서 평균을 제거한다. 현재 파형을 k만큼 뒤에서 읽었을 때 기준 파형과 얼마나 닮았는지 계산한다. 이 k는 SVD rank 또는 Fourier 절단 차수가 아니다.
%[text]{"align":"center"} $ G\_p(k)=\\frac{\\sum\_n \\tilde r\[n\]^\*\\tilde v\_p\[n+k\]}{\\sqrt{\\sum\_n |\\tilde r\[n\]|^2\\sum\_n |\\tilde v\_p\[n+k\]|^2}} $
%[text]{"align":"center"} $ \\hat k\_p=\\arg\\max\_k G\_p(k) $
%[text] 현재 AM/power 분석에서는 실수 상관의 최댓값을 쓴다. 복소 IQ에서는 위상과 CFO 가정을 먼저 정해야 한다. 상관의 절댓값을 쓰면 상수 위상 차이에 대한 불변성을 얻지만 polarity 구분은 사라질 수 있다.
%[text] 정수 격자 사이의 피크는 주변 세 점으로 포물선을 맞춰 추정한다. 이는 추가 측정 해상도나 신뢰구간을 보장하지 않는다.
%[text]{"align":"center"} $ \\delta=\\frac{G(k-1)-G(k+1)}{2\[G(k-1)-2G(k)+G(k+1)\]},\\qquad \\tilde k=k+\\delta $
%[text] **두 그래프를 구분한다:** 가로축 k인 G(k) 곡선은 한 관측의 지연 탐색이다. 가로축 p인 지연 추적 그래프는 여러 프레임에서 피크 위치가 어떻게 변하는지 나타낸다.
%%
%[text] ## 템플릿을 만들고 다른 구간에 적용
%[text] 짧은 파형은 RF78 subband의 첫 블록 0.2초부터 약 135 ms로 학습했다. 고정한 주기 위상에 따라 power를 128개 bin으로 평균한다. 1.1초와 1.8초 블록에서 템플릿을 다시 만들지 않는다.
%[text]{"align":"center"} $ u\_i=\\operatorname{frac}(f\_0t\_i),\\qquad r\[j\]=\\frac{1}{|\\mathcal B\_j|}\\sum\_{i\\in\\mathcal B\_j}|x\[i\]|^2 $
%[text] 각 검증 블록을 32구간으로 나눴다. 각 구간의 앞 절반으로 지연을 추정하고, 뒤 절반에 그 지연을 적용해 평가했다. 하나의 검증 구간에서 지연과 성능을 동시에 최적화하지 않았다.
%[text] 한 프레임 템플릿은 원본 AM의 줄별 평균을 첫 24프레임에서 평균했다. 한 프레임을 guard로 남겼으며, 이후 114프레임을 검증했다. 프레임 길이 ACF 탐색도 학습 구간만 사용했다.
periodNumbers27 = table(shortResult27.shortMeta.frozen_frequency_hz,shortResult27.shortMeta.period_us,shortResult27.shortMeta.native_samples_per_period,shortResult27.shortMeta.analysis_samples_per_period,'VariableNames',{'CycleHz','PeriodMicroseconds','NativeSamplesPerCycle','SubbandSamplesPerCycle'}) %[output:54f64ba8]
frameNumbers27 = table(frameResult27.frameMeta.training_acf_lines,frameResult27.frameMeta.training_delay_slope_lines_per_frame,frameResult27.frameMeta.tested_frames,'VariableNames',{'RowsPerFrame','TrainingLagSlopeRowsPerFrame','ValidationFrames'}) %[output:70a07282]
%%
%[text] ## FAM: 짧은 FFT와 느린 시간축 FFT
%[text] FAM은 서로 다른 주파수 성분의 관계가 어떤 주기로 반복되는지 찾는다. 여기서 M은 짧은 FFT 길이, L은 창 이동 샘플 수, P는 창 개수이다. 각 짧은 FFT의 시작 시각을 보상한 채널 출력을 D로 쓴다.
%[text]{"align":"center"} $ D\_k\[r\]=e^{-j2\\pi krL/M}\\sum\_{m=0}^{M-1}a\[m\]x\[rL+m\]e^{-j2\\pi km/M} $
%[text] 비켤레(non-conjugate) 순환통계는 아래처럼 한쪽 채널을 켤레화한다. 명칭의 non-conjugate와 곱에 별표가 나타나는 것을 혼동하지 않는다.
%[text]{"align":"center"} $ Z\_{kl}\[q\]=\\sum\_{r=0}^{P-1}g\[r\]D\_k\[r\]D\_l\[r\]^\*e^{-j2\\pi qr/P} $
%[text] 빠른 FFT의 두 채널 차이에 느린 FFT의 residual 주파수를 더해야 순환주파수 alpha가 된다.
%[text]{"align":"center"} $ f=\\frac{f\_k+f\_l}{2},\\qquad \\alpha=f\_k-f\_l+q\\frac{F\_s}{PL},\\qquad f\_k=k\\frac{F\_s}{M} $
%[text] 따라서 k=l이어도 q가 0이 아니면 alpha가 0이 아닌 피크가 나온다. 실제 첫 번째 후보가 바로 이 경우다.
pairNumbers27 = struct2table(famResult27.metadata.pairs);
pairNumbers27(:,{'k','l','q','rf_pair_midpoint_hz','coarse_difference_hz','residual_hz','alpha_hz','correlation_magnitude'}) %[output:536899b2]
%%
%[text] ## FAM 그래프 색과 해상도
%[text] 채널쌍 곱을 각 채널의 에너지로 정규화한 유한 창 상관을 표시한다. 이상적인 점별 spectral coherence, SNR, 복호 성공률, 검정 p-value와 구분한다.
%[text]{"align":"center"} $ C\_{kl}\[q\]=\\frac{Z\_{kl}\[q\]}{\\sqrt{(\\sum\_r g\[r\]|D\_k\[r\]|^2)(\\sum\_r g\[r\]|D\_l\[r\]|^2)}} $
%[text]{"align":"center"} $ \\Delta f=\\frac{F\_s}{M}=242349.21875\\ \\mathrm{Hz},\\qquad \\Delta\\alpha=\\frac{F\_s}{PL}=7.395911\\ \\mathrm{Hz} $
%[text] FAM 열지도의 가로축은 반복주파수 alpha이고, 세로축은 비켤레 통계의 nominal RF pair midpoint이다. 색은 해당 표시 셀에 들어온 추정값 중 최대 상관이다. CDP는 alpha마다 검사한 채널쌍의 최대값을 표시한다.
%[text] 112802.437878 Hz는 FAM 격자상의 후보이고 112802.550197 Hz는 학습 블록의 cyclic power를 추가 최적화한 값이다. 소수점 자릿수는 측정 정확도를 뜻하지 않는다.
%%
%[text] ## CFO와 시간 지연의 구분
%[text] 아래 관계는 이상적인 비켤레 SCF에 대한 식이다. 실제 유한 채널쌍에서는 필터 가중치 변화도 고려해야 한다.
%[text]{"align":"center"} $ y(t)=e^{j2\\pi\\Delta f t}x(t-\\tau)\\quad\\Rightarrow\\quad S\_y^\\alpha(f)=e^{-j2\\pi\\alpha\\tau}S\_x^\\alpha(f-\\Delta f) $
%[text] 상수 CFO는 주로 f축을 이동시킨다. 지연은 alpha에 비례하는 순환위상을 만든다. AM/power 템플릿으로 얻은 지연을 CFO 추정값으로 해석하지 않는다.
%%
%[text] ## 검증 결과와 반례
%[text] 짧은 검증 구간의 상관 중앙값은 0.921238에서 0.924725로 변했다. 64구간 중 56구간은 높아졌지만, 8구간은 낮아졌고 그중 두 구간은 약 0.99만큼 크게 하락했다. 평균파형의 높은 일치도만으로 모든 시각에 동일한 템플릿을 적용할 수 있다고 결론내릴 수 없다.
%[text] 프레임의 학습 기울기는 약 -0.000456줄/frame이다. 그러나 검증 지연의 RMS는 0 지연 기준 0.01613줄에서 학습 기울기 예측 기준 0.04070줄로 악화됐다. 이 drift 모델을 후속 stitching의 자동 시간축 보정으로 채택하지 않는다.
auditNumbers27 = table(failureResult27.short_number_improved,failureResult27.short_number_degraded,failureResult27.short_number_large_losses_over_0p1,failureResult27.frame_test_zero_delay_rms_lines,failureResult27.frame_test_training_prediction_rms_lines,'VariableNames',{'ImprovedWindows','DegradedWindows','LargeFailures','ZeroDelayRmsRows','PredictedDriftRmsRows'}) %[output:7ed7c31b]
%[text] 약 0.88 us의 큰 지연 추정은 주로 특정 프레임 위상에 모인다. 파형 상태 변화 또는 다른 펄스 선택이라는 가설과 부합하지만, packet 상태를 복호한 결과는 아니다.
